    INF = 99
    L = []
    cur = 0
    for i in range(N):
        L.append(X[i]-cur)
        cur = X[i]
    dp = [[[INF]*(H+1) for _ in range(H+1)] for _ in range(N+1)]
    P.append(0)
    F.append(0)
    for i in range(N+1):
        for j in range(H+1):
            dp[i][j][0] = INF
    dp[0][H][0] = 0

