        for j in range(H+1):
            for k in range(1, H+1):
                if dp[i][j][k] == INF:
                    continue
                if j-L[i] < 0:
                    continue
                # 往路で利用するとき
                dp[i+1][min(j-L[i]+F[i], H)][k-1] = min(dp[i][j][k]+P[i], dp[i+1][min(j-L[i]+F[i], H)][k-1])
                # 復路で利用するとき
