                        dp[i+1][j-L[i]][k-F[i]] = min(dp[i][j][k]+P[i], dp[i+1][j-L[i]][k-F[i]])

    ans = INF
    for i in range(H+1):
        ans = min(ans, dp[N][i][0])
    if ans == INF:
