def solve(graph, n, m, max_weight):
    visited = [-1] * (n + 1)

    def bfs(start):
        que = [start]
        visited[start] = 0
        while que:
            v = que.pop(0)
            for nv, c in graph[v]:
                if c > max_weight:
                    break
                if visited[nv] == -1:
                    visited[nv] = visited[v] ^ 1
                    que.append(nv)
                elif visited[nv] == visited[v]:
                    return False
        return True

    for i in range(1, n + 1):
        if visited[i] != -1:
            continue
        if not bfs(i):
            return False
    return True

