N,T,M=map(int,input().split())
#たかだか10人しかいません
hate=set()

for _ in range(M):
    a,b=map(int,input().split())
    hate.add((a-1,b-1))
    hate.add((b-1,a-1))

def f(now, teams):
    if now==N:
        #nowをNから波及させていくが、そのとき、ちゃんとteamsがTになっていれば1を返すようにする。
        return 1 if len(teams)==T else 0

    ans=0

    for i in range(len(teams)):
        if len(teams[i])>0:
            for t in teams[i]:
                if (now,t) in hate:
                    #相性悪い人がいる場合
                    break
            else:
                #いない場合
                teams[i].add(now)
                ans+=f(now+1, teams[:])
                teams[i].remove(now)

    if len(teams)<T:
        teams.append(set([now]))
        ans+=f(now+1, teams[:])
        teams.pop()

    return ans

teams=[]
